import{c as t,Q as r,j as e,m as o}from"./chunks/framework.BPKcPtvA.js";const g=JSON.parse('{"title":"Voucher Hotspot","description":"","frontmatter":{},"headers":[],"relativePath":"panduan/hotspot/voucher.md","filePath":"panduan/hotspot/voucher.md"}'),n={name:"panduan/hotspot/voucher.md"};function s(i,a,d,u,h,l){return r(),e("div",null,[...a[0]||(a[0]=[o('<h1 id="voucher-hotspot" tabindex="-1">Voucher Hotspot <a class="header-anchor" href="#voucher-hotspot" aria-label="Permalink to &quot;Voucher Hotspot&quot;">​</a></h1><hr><h2 id="melihat-daftar-voucher" tabindex="-1">Melihat Daftar Voucher <a class="header-anchor" href="#melihat-daftar-voucher" aria-label="Permalink to &quot;Melihat Daftar Voucher&quot;">​</a></h2><p>Buka router → <strong>Hotspot → Voucher</strong></p><p>Tabel menampilkan semua voucher dengan status:</p><table tabindex="0"><thead><tr><th>Status</th><th>Arti</th></tr></thead><tbody><tr><td>🟡 <strong>Belum dipakai</strong></td><td>Voucher siap digunakan</td></tr><tr><td>🟢 <strong>Aktif</strong></td><td>Voucher sedang digunakan</td></tr><tr><td>⚫ <strong>Kedaluwarsa</strong></td><td>Masa berlaku habis</td></tr></tbody></table><hr><h2 id="generate-voucher" tabindex="-1">Generate Voucher <a class="header-anchor" href="#generate-voucher" aria-label="Permalink to &quot;Generate Voucher&quot;">​</a></h2><ol><li>Klik <strong>+ Generate Voucher</strong></li><li>Isi pengaturan:</li></ol><table tabindex="0"><thead><tr><th>Field</th><th>Keterangan</th></tr></thead><tbody><tr><td><strong>Profil</strong></td><td>Pilih profil hotspot yang sudah dibuat</td></tr><tr><td><strong>Jumlah</strong></td><td>Berapa voucher yang ingin dibuat (1–500)</td></tr><tr><td><strong>Panjang Username</strong></td><td>Jumlah karakter username (default 6–8)</td></tr><tr><td><strong>Panjang Password</strong></td><td>Jumlah karakter password (default 6–8)</td></tr><tr><td><strong>Charset Username</strong></td><td>Karakter yang digunakan untuk username: huruf, angka, atau kombinasi</td></tr><tr><td><strong>Charset Password</strong></td><td>Karakter yang digunakan untuk password</td></tr></tbody></table><ol start="3"><li>Klik <strong>Generate</strong> — voucher langsung dibuat dan disync ke MikroTik</li></ol><hr><h2 id="cetak-voucher" tabindex="-1">Cetak Voucher <a class="header-anchor" href="#cetak-voucher" aria-label="Permalink to &quot;Cetak Voucher&quot;">​</a></h2><ol><li>Centang voucher yang ingin dicetak, atau centang semua</li><li>Klik <strong>Cetak</strong> — halaman cetak terbuka dengan tampilan kartu voucher yang siap dicetak</li></ol><p>Setiap kartu voucher menampilkan:</p><ul><li>Nama bisnis Anda</li><li>Username &amp; password</li><li>Profil/paket</li><li>Durasi akses</li></ul><hr><h2 id="hapus-voucher" tabindex="-1">Hapus Voucher <a class="header-anchor" href="#hapus-voucher" aria-label="Permalink to &quot;Hapus Voucher&quot;">​</a></h2><p>Voucher yang sudah <strong>Aktif</strong> atau <strong>Kedaluwarsa</strong> bisa dihapus dari sistem dan MikroTik dengan mengklik ikon hapus di baris voucher.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Generate voucher dalam jumlah besar sekaligus dan simpan fisiknya. Voucher yang belum dipakai tidak memakan resource di MikroTik.</p></div>',20)])])}const k=t(n,[["render",s]]);export{g as __pageData,k as default};
